  NUMBER_SCRATCH.value = value.TurretIndex;
  if (!stream.serializeBits(NUMBER_SCRATCH, 8)) {
    return false;
  }
  if (!WriteQuat(stream, value.Rotation)) {
    return false;
  }
  BIGINT_SCRATCH.value = value.Flags;
  if (!stream.serializeBits64(BIGINT_SCRATCH, 64)) {
    return false;
  }
  return true;
